/// <summary>
/// PaffH 04.02.23
/// </summary>
/// <returns>NDXProdIdentPackagingFromAX2009</returns>
public static NDXProdIdentPackagingFromAX2009 construct()
{
    NDXProdIdentPackagingFromAX2009 nDXProdIdentPackagingFromAX2009 = new NDXProdIdentPackagingFromAX2009();
    return nDXProdIdentPackagingFromAX2009;
}

/// <summary>
/// PaffH 04.02.23
/// </summary>
/// <returns>System.Threading.Tasks.Task</returns>
public static System.Threading.Tasks.Task runAsyc()
{
    System.Threading.Tasks.Task task;
    Dialog dialog = new Dialog();
    dialog.addText("@NDX:NDXTransferOfProductLabelsFromAX2009");
    DialogField fieldMaxRunTime = dialog.addFieldValue(extendedTypeStr(NDXID), 1, "@NDX:NDXMaxRuntimeForAzureQueueQuery");
    DialogField fieldDeleteActualData = dialog.addFieldValue(extendedTypeStr(NoYesId), NoYes::No, "@NDX:NDXDeleteExistingTransferData");
    DialogField fieldRunWithoutAction = dialog.addFieldValue(extendedTypeStr(NoYesId), NoYes::No, "@NDX:NDXRemoveContractsWithoutProcessingFromAzureQueue");
    dialog.run();
    if (dialog.closedOk())
    {
        int maxRunTime = fieldMaxRunTime.value();
        NoYes deleteActualData = fieldDeleteActualData.value();
        NoYes runWithoutAction = fieldRunWithoutAction.value();
        task = runAsync(
            classNum(NDXProdIdentPackagingFromAX2009),
            staticMethodStr(NDXProdIdentPackagingFromAX2009,runableForAsyncCall),
            [maxRunTime, deleteActualData, runWithoutAction],
            System.Threading.CancellationToken::None,
            classNum(NDXProdIdentProcedureFromAX2009),
            staticMethodStr(NDXProdIdentProcedureFromAX2009,asyncResult));
    }
    return task;
}

/// <summary>
/// PaffH 04.02.23
/// </summary>
/// <param name = "_params">container</param>
/// <returns>container</returns>
public static container runableForAsyncCall(container _params)
{
    container conRet = conNull();
    int maxRuntimeInMinutes = conPeek(_params, 1);
    NoYes deleteActualData = conPeek(_params, 2);
    NoYes runWithoutAction = conPeek(_params, 3);
    NDXProdIdentPackagingFromAX2009 nDXProdIdentPackagingFromAX2009 = NDXProdIdentPackagingFromAX2009::construct();
    nDXProdIdentPackagingFromAX2009.ParmDeleteActualData(deleteActualData);
    nDXProdIdentPackagingFromAX2009.ParmRunWithoutAction(runWithoutAction);
    nDXProdIdentPackagingFromAX2009.ReadContractsFromQueue(maxRuntimeInMinutes);
    return conRet;
}

/// <summary>
/// PaffH 04.02.23
/// </summary>
protected void deleteActualData()
{
    NDXProdIdentPackaging nDXProdIdentPackaging;
    delete_from nDXProdIdentPackaging;
}

/// <summary>
/// PaffH 04.02.23
/// </summary>
/// <param name = "_maxRuntimeInMinutes">int</param>
public void readContractsFromQueue(int _maxRuntimeInMinutes = 0)
{
    maxRuntimeInMinutes = _maxRuntimeInMinutes;

    NDXProdIdentPackaging nDXProdIdentPackaging;
    boolean loopOK = true;
    int recCount1, recCount2, recCount3, countReadFromQueue, countRuns;
    NDXProdIdentPackagingContract nDXProdIdentPackagingContract, nDXProdIdentPackagingContractLast;
    ProdIdentPackagingFromAX2009 prodIdentPackagingFromAX2009 = new ProdIdentPackagingFromAX2009(connectionString, azureQueueName);

    int sleepDuration = 1000;
    secStart = NDXHelperCommon::timeNow();
    int secStartRun = secStart;
    int secEnd, diffSec;
    str errInfo;
    const str dataAreaIdDefault = 'NDX';
    NDXDataTransferErrorClass dataTransferError = NDXDataTransferErrorClass::construct(tableNum(NDXProdIdentPackaging));
    recCount1 = 0;
    recCount2 = 0;
    recCount3 = 0;
    countReadFromQueue = 0;
    countRuns = 0;
    int runtimeInMinutes;
    nDXProdIdentPackagingContractLast = null;
    isReadingFromQueue = true;
    info(strFmt('Start : [%1]', NDXHelperCommon::seconds2Str()));
    if (deleteActualData == NoYes::Yes)
    {
        this.deleteActualData();
        dataTransferError.deleteExistingLog();
    }
    while (loopOK)
    {
        nDXProdIdentPackaging = null;
        nDXProdIdentPackagingContract = prodIdentPackagingFromAX2009.Receive1MessageValuesD365FO(true).Contract;
        if (runWithoutAction == NoYes::Yes)
        {
            if (nDXProdIdentPackagingContract == null)
            {
                break;
            }
            else
            {
                continue;
            }
        }


        if (nDXProdIdentPackagingContract == null && nDXProdIdentPackagingContractLast == null)
        {
            secEnd = NDXHelperCommon::timeNow();
            runtimeInMinutes = real2int((secEnd - secStart) / 60);
            if (maxRuntimeInMinutes != 0 && runtimeInMinutes >= maxRuntimeInMinutes)
            {
                break;
            }
            else
            {
                sleep(sleepDuration);
                continue;
            }
        }

        ++countReadFromQueue;
        if (nDXProdIdentPackagingContract == null && nDXProdIdentPackagingContractLast != null)
        {
            nDXProdIdentPackagingContractLast = null;
            ++countRuns;
            secEnd = NDXHelperCommon::timeNow();
            diffSec = secEnd - secStartRun;
            Info(strFmt('%1.) Dauer: [%2]', countRuns, NDXHelperCommon::seconds2Str(diffSec)));
            Info(strFmt('%1.) Azure-Queue Lesevorgänge: [%2]', countRuns, countReadFromQueue));
            Info(strFmt('%1.) Anzahl DS: Artikel[%2] [%3][%4]', countRuns, recCount1, recCount2, recCount3));
            runtimeInMinutes = real2int((secEnd - secStart) / 60);
            if (maxRuntimeInMinutes != 0 && runtimeInMinutes >= maxRuntimeInMinutes)
            {
                break;
            }
            else
            {
                sleep(sleepDuration);
                continue;
            }
        }
        else
        {
            nDXProdIdentPackagingContractLast = nDXProdIdentPackagingContract;
            secStartRun = NDXHelperCommon::timeNow();
        }

        // read data from: nDXProdIdentPackaging - Contract
        IEnumerable tList = nDXProdIdentPackagingContract.NDXProdIdentPackagingTableContract;
        IEnumerator enum = tList.GetEnumerator();
        while (enum.moveNext())
        {
            ++recCount1;
            errInfo = '';
            NDXProdIdentPackagingTableContract nDXProdIdentPackagingTableContract = enum.current;

            if (nDXProdIdentPackagingTableContract.ItemIdPacking != '')
            {
                DataAreaId uk = NDXHelperItem::DataAreaIdFromItemId(nDXProdIdentPackagingTableContract.ItemIdPacking, dataAreaIdDefault);
                changecompany(uk)
                {
                    nDXProdIdentPackaging = NDXProdIdentPackaging::findOrCreateItemId(nDXProdIdentPackagingTableContract.ItemIdPacking, true);
                    if (!nDXProdIdentPackaging.InventTable)
                    {
                        dataTransferError.addError(nDXProdIdentPackaging.RecId, NDXErrorMessageClass::construct(
                                                    "@NDX:NDXProdIdentItemNotFound",
                                                    strFmt("@NDX:NDXProdIdentItemNotFoundDetail",
                                                    nDXProdIdentPackagingTableContract.ItemIdPacking)));
                        continue;
                    }
                    nDXProdIdentPackaging.Active = nDXProdIdentPackagingTableContract.Active;
                    nDXProdIdentPackaging.UpdatedUTC = nDXProdIdentPackagingTableContract.UpdatedUTC;
                    nDXProdIdentPackaging.Counter = nDXProdIdentPackagingTableContract.Counter;
                    if (nDXProdIdentPackagingTableContract.ProdIdentLabelIdNew)
                    {
                        NDXProdIdentLabel nDXProdIdentLable = NDXProdIdentLabel::find(nDXProdIdentPackagingTableContract.ProdIdentLabelIdNew);
                        if (nDXProdIdentLable)
                        {
                            nDXProdIdentPackaging.NDXProdIdentLabel = nDXProdIdentLable.RecId;
                        }
                        else
                        {
                            dataTransferError.addError(nDXProdIdentPackaging.RecId, NDXErrorMessageClass::construct(
                                                    "@NDX:NDXProdIdentLabelNotFound",
                                                    strFmt("@NDX:NDXProdIdentLabelNotFoundDetail",
                                                    nDXProdIdentPackagingTableContract.ProdIdentLabelIdNew)));
                        }
                    }
                    if (nDXProdIdentPackagingTableContract.TechniqueId)
                    {
                        NDXProdIdentTechnique nDXProdIdentTechnique = NDXProdIdentTechnique::find(nDXProdIdentPackagingTableContract.TechniqueId);
                        if (nDXProdIdentTechnique)
                        {
                            nDXProdIdentPackaging.NDXProdIdentTechnique = nDXProdIdentTechnique.RecId;
                        }
                        else
                        {
                            dataTransferError.addError(nDXProdIdentPackaging.RecId, NDXErrorMessageClass::construct(
                                                        "@NDX:NDXProdIdentTechniqueIdNotFound",
                                                        strFmt("@NDX:NDXProdIdentTechniqueIdNotFoundDetail",
                                                        nDXProdIdentPackagingTableContract.TechniqueId)));
                        }
                    }
                    if (nDXProdIdentPackagingTableContract.UnitIdFilter)
                    {
                        UnitOfMeasure unitOfMeasure = UnitOfMeasure::findBySymbol(nDXProdIdentPackagingTableContract.UnitIdFilter);
                        if (unitOfMeasure)
                        {
                            nDXProdIdentPackaging.UnitOfMeasure = unitOfMeasure.RecId;
                        }
                        else
                        {
                            dataTransferError.addError(nDXProdIdentPackaging.RecId, NDXErrorMessageClass::construct(
                                                        "@NDX:NDXProdIdentUnitIdNotFound",
                                                        strFmt("@NDX:NDXProdIdentUnitIdNotFoundDetail",
                                                        nDXProdIdentPackagingTableContract.UnitIdFilter)));
                        }
                    }
                    ttsbegin;
                    nDXProdIdentPackaging.write();
                    ttscommit;
                }
            }
            else
            {
                continue;
            }
        }
    }
    dataTransferError.endError();
    secEnd = NDXHelperCommon::timeNow();
    Info(strFmt('Gesamtlaufzeit: [%1]', NDXHelperCommon::seconds2Str(secEnd - secStart)));
    isReadingFromQueue = false;
}
